const A = [0.29783,0.07434,0.15836,-0.13982], O = [1145,42.8];
const G0 = [1116.655,-71.342], GJ = [1121.352,-70.169], GI = [1112.256,-67.457];
const SLIDE = [5.3657,1.3394];
const LEVELS = [0.18,0.4,0.62,0.84];
const SECONDS_PER_STEP = 1;
const stage = document.querySelector(".scene-cyclone");
const svg = stage.querySelector("svg");
const still = matchMedia("(prefers-reduced-motion: reduce)");
const slots = new Map([...svg.querySelectorAll("[data-low]")].map((g) => [Number(g.dataset.low), g]));
